/* Trajectoire AR(1) : mean reversion (|ϕ|<1) vs marche aléatoire (ϕ=1) vs explosif (ϕ>1) */
(function () {
  var svg = document.getElementById("ts-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  // Chocs déterministes (LCG + Box-Muller, seed fixe) : la trajectoire reste stable entre réglages
  function makeNormals(count, seed){
    var out=[];
    function rnd(){ seed=(1103515245*seed+12345)&0x7fffffff; return seed/0x7fffffff; }
    for (var i=0;i<count;i++){
      var u1=Math.max(rnd(),1e-9), u2=rnd();
      out.push(Math.sqrt(-2*Math.log(u1))*Math.cos(2*Math.PI*u2));
    }
    return out;
  }
  var N=120, Z = makeNormals(N, 135792468);

  function draw(){
    var phi=v("ts-phi"), delta=v("ts-delta"), sigma=v("ts-sigma");
    setT("ts-phi-o", phi.toFixed(2)); setT("ts-delta-o", delta.toFixed(1)); setT("ts-sigma-o", sigma.toFixed(1));

    var stationary = phi < 1;
    var mu = stationary ? delta/(1-phi) : null;
    // trajectoire
    var ys=[], y = stationary ? mu : 0; // départ : la moyenne si stationnaire, sinon 0
    for (var i=0;i<N;i++){ y = delta + phi*y + sigma*Z[i]; ys.push(y); }

    setT("ts-mean", stationary ? mu.toFixed(2) : (al()==="en"?"undefined":(al()==="nl"?"ongedefinieerd":"non définie")));
    var vword;
    if (phi < 1) vword = stationary ? (sigma*sigma/(1-phi*phi)).toFixed(2) : "—";
    else vword = al()==="en"?"grows (t·σ²)":(al()==="nl"?"groeit (t·σ²)":"croît (t·σ²)");
    setT("ts-var", vword);

    var dec = document.getElementById("ts-dec");
    var reg;
    if (phi < 0.999){ reg = al()==="en"?"Stationary (mean reversion)":(al()==="nl"?"Stationair (mean reversion)":"Stationnaire (mean reversion)"); dec.style.color="var(--teal)"; }
    else if (phi <= 1.001){ reg = al()==="en"?"Random walk (unit root)":(al()==="nl"?"Random walk (unit root)":"Marche aléatoire (unit root)"); dec.style.color="var(--gold)"; }
    else { reg = al()==="en"?"Explosive":(al()==="nl"?"Explosief":"Explosif"); dec.style.color="var(--crimson)"; }
    dec.textContent = reg;

    // échelle
    var W=520,H=300,L=44,R=16,T0=16,B=30, pw=W-L-R, ph=H-T0-B;
    var ymin=Infinity,ymax=-Infinity;
    for (i=0;i<N;i++){ if(ys[i]<ymin)ymin=ys[i]; if(ys[i]>ymax)ymax=ys[i]; }
    if (stationary){ if(mu<ymin)ymin=mu; if(mu>ymax)ymax=mu; }
    var pad=(ymax-ymin)*0.10||1; ymin-=pad; ymax+=pad;
    function px(t){ return L + t/(N-1)*pw; }
    function py(val){ return T0 + (1-(val-ymin)/(ymax-ymin))*ph; }

    var g="";
    // axes
    g+='<line class="axis" x1="'+L+'" y1="'+(T0+ph)+'" x2="'+(L+pw)+'" y2="'+(T0+ph)+'"/>';
    g+='<line class="axis" x1="'+L+'" y1="'+T0+'" x2="'+L+'" y2="'+(T0+ph)+'"/>';
    // moyenne long terme (si stationnaire)
    if (stationary){
      var ym=py(mu);
      g+='<line x1="'+L+'" y1="'+ym.toFixed(1)+'" x2="'+(L+pw)+'" y2="'+ym.toFixed(1)+'" stroke="var(--crimson)" stroke-width="1.4" stroke-dasharray="5 4"/>';
      var mlab = al()==="en"?"long-run mean":(al()==="nl"?"LT-gemiddelde":"moyenne LT");
      g+='<text class="tick" x="'+(L+pw)+'" y="'+(ym-4).toFixed(1)+'" text-anchor="end" fill="var(--crimson)">'+mlab+' '+mu.toFixed(1)+'</text>';
    }
    // trajectoire
    var d="";
    for (i=0;i<N;i++){ d+=(i===0?"M ":" L ")+px(i).toFixed(1)+","+py(ys[i]).toFixed(1); }
    g+='<path d="'+d+'" fill="none" stroke="var(--teal)" stroke-width="2"/>';
    // libellés axes
    var xlab = al()==="en"?"time t":(al()==="nl"?"tijd t":"temps t");
    g+='<text class="lab" x="'+(L+pw)+'" y="'+(T0+ph+16)+'" text-anchor="end">'+xlab+'</text>';
    g+='<text class="lab" x="'+L+'" y="'+(T0-4)+'" text-anchor="start">Yₜ</text>';
    svg.innerHTML=g;
  }
  ["ts-phi","ts-delta","ts-sigma"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
